/// <summary>
/// On Modified event handler for Address search control
/// </summary>
/// <param name="_sender">Form data source</param>
/// <param name="_e">Event args</param>
[FormControlEventHandler(formControlStr(LogisticsPostalAddress, METAddressSearch), FormControlEventType::Modified),
    SuppressBPWarningAttribute("BPParameterNotUsed", "@MET:BPParameterNotUsedMessage")]
public static void METAddressSearch_OnModified(FormControl _sender, FormControlEventArgs _e)
{
    FormStringControl addressSearch = _sender as FormStringControl;
    FormFunctionButtonControl metSearchAddress = _sender.formRun().design().controlName(formControlStr(LogisticsPostalAddress, METSearchAddress));

    if (strLen(addressSearch.text()) > 10 && strLen(strRem(addressSearch.text(), METConstants::space)) > 0)
    {
        metSearchAddress.enabled(true);
        metSearchAddress.defaultButton(true);
    }
    else
    {
        metSearchAddress.enabled(false);
    }
}
